from __future__ import annotations

import json
import os
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
TOP_FILE = SOURCE_DIR / "polyply" / "tests" / "test_data" / "topology_test" / "system.top"
BLD_FILE = SOURCE_DIR / "polyply" / "tests" / "test_data" / "topology_test" / "test.bld"
OUTPUT_DIR = TASK_DIR / "outputs"
REPORT_FILE = OUTPUT_DIR / "public_reproduction_report.json"
OUTPUT_FILE = OUTPUT_DIR / "public_reproduction_output.gro"

os.environ.setdefault("NUMBA_DISABLE_JIT", "1")
sys.path.insert(0, str(SOURCE_DIR))


def write_report(report: dict[str, object], exit_code: int) -> int:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def inspect_output(path: Path) -> dict[str, object]:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    return {
        "exists": path.exists(),
        "byte_count": path.stat().st_size,
        "line_count": len(lines),
        "atom_count": int(lines[1].strip()) if len(lines) > 1 else None,
    }


def main() -> int:
    try:
        from polyply.src.gen_coords import gen_coords  # noqa: E402
    except Exception as exc:  # noqa: BLE001 - infrastructure failures need a report.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "workflow": "coordinate_generation",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    OUTPUT_FILE.parent.mkdir(parents=True, exist_ok=True)
    if OUTPUT_FILE.exists():
        OUTPUT_FILE.unlink()

    try:
        gen_coords(
            TOP_FILE,
            OUTPUT_FILE,
            "test",
            build=[BLD_FILE],
            box=[10.0, 10.0, 10.0],
        )
    except Exception:  # noqa: BLE001 - this is the scientific failure path.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "workflow": "coordinate_generation",
                "output": {
                    "exists": OUTPUT_FILE.exists(),
                },
            },
            1,
        )

    output_observation = inspect_output(OUTPUT_FILE)
    completed = bool(output_observation["exists"] and output_observation["line_count"] > 0)
    return write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed" if completed else "runner_failure",
            "workflow": "coordinate_generation",
            "output": output_observation,
        },
        0 if completed else 2,
    )


if __name__ == "__main__":
    raise SystemExit(main())

